package io.github.diodeme.ji.host;

/**
 * Canonical Host identity (chapter 18 §4): the persisted {@code hostId} and the revision that guards
 * concurrent renames. Every value derived from the Host identity (Relay registration, device
 * authorization scope, artifact scope, client routes) reads this record, so a rename cannot leave a
 * stale copy behind.
 */
public record HostIdentity(String hostId, long revision) {
    /** Accepted ids: the id is a Relay management path segment, so it stays URL-safe. */
    public static final String PATTERN = "[A-Za-z0-9][A-Za-z0-9._-]{0,127}";
    private static final java.util.regex.Pattern FORMAT = java.util.regex.Pattern.compile(PATTERN);
    private static final int GENERATED_BYTES = 8;

    public HostIdentity {
        requireValid(hostId);
        if (revision < 0) throw new IllegalArgumentException("hostId revision must not be negative");
    }

    /** @return the accepted id; throws the stable structured rejection otherwise. */
    public static String requireValid(String hostId) {
        if (hostId == null || !FORMAT.matcher(hostId).matches()) {
            throw new HostIdentityException("format", hostId);
        }
        return hostId;
    }

    /** Generates a stable, collision-resistant id for a Host that has never persisted one. */
    public static String generate() {
        byte[] value = new byte[GENERATED_BYTES];
        new java.security.SecureRandom().nextBytes(value);
        return "host-" + java.util.HexFormat.of().formatHex(value);
    }
}
```

